"""
    Get sign of the given number

    :param number:
    :type number: int

    :return: -1, 0, 1
    :rtype: int
    """
def _sign(number: Any) -> object {
    if (number > 0) {
        return 1;
    }
    if (number < 0) {
        return -1;
    }
    return 0;
}

